package com.mendes.scheduling_platform.security;
import com.mendes.scheduling_platform.tenant.*; import jakarta.servlet.FilterChain; import org.junit.jupiter.api.*; import org.springframework.mock.web.*; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class JwtAuthenticationFilterTest { private final TenantRepository tenants=mock(TenantRepository.class);private final JwtService jwt=new JwtService("test-secret-with-more-than-thirty-two-characters",60_000);private final JwtAuthenticationFilter filter=new JwtAuthenticationFilter(jwt,tenants);@AfterEach void clear(){TenantContext.clear();}
 @Test void rejectsAlreadyIssuedTokenWhenTenantWasSuspended()throws Exception{Tenant tenant=new Tenant();tenant.setId(1L);tenant.setStatus(Tenant.TenantStatus.SUSPENDED);when(tenants.findById(1L)).thenReturn(Optional.of(tenant));MockHttpServletRequest request=new MockHttpServletRequest("GET","/venues");request.addHeader("Authorization","Bearer "+jwt.issue("user@test.com",1L,"OWNER",false));MockHttpServletResponse response=new MockHttpServletResponse();FilterChain chain=mock(FilterChain.class);filter.doFilter(request,response,chain);assertEquals(403,response.getStatus());verifyNoInteractions(chain);}}
